steps.seedCode:
// Import the necessary Angular modules here
import { Component } from '@angular/core';
import { FormsModule } from '@angular/forms';

// Create your ControlledInputComponent here
@Component({
  selector: 'app-controlled-input',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div>
      <input type="text" [value]="inputValue" (input)="onInputChange($event)" />
      <button (click)="clearInput()">Clear</button>
      <p>You typed: {{inputValue}}</p>
      <span>Character count: {{inputValue.length}}</span>
    </div>
  `
})
export class ControlledInputComponent {
  inputValue: string = '';

  onInputChange(event: Event) {
    const target = event.target as HTMLInputElement;
    this.inputValue = target.value;
  }

  clearInput() {
    this.inputValue = '';
  }
}
